}
#preferences-prompt .preferences-cards .contacts-img {
  float: left;
  margin-left: 5px;
  padding-left: 5px;
}
#preferences-prompt .preferences-cards .crm-email-container {
  color: #D7DBDE;
  font-size: 12px;
  padding-top: 17px;
  padding-bottom: 10px;
  height: 60px;
}
#preferences-prompt .preferences-cards .crm-email-container ::placeholder {
  color: #D7DBDE;
  opacity: 1;
  /* Firefox */
}
#preferences-prompt .preferences-cards .enabled-style {
  color: #333839;
}
#preferences-prompt .preferences-cards .active-style {
  color: #29ABE2;
}
#preferences-prompt .preferences-cards .bcc-address, #preferences-prompt .preferences-cards .bcc-address-disabled {
  width: 240px;
  height: 30px;
  font-size: 14px;
  display: none;
}
#preferences-prompt .preferences-cards .required-style {
  color: #E74C3C;
  display: none;
  padding-top: 5px;
}
#preferences-prompt .preferences-cards .error-style {
  color: #E74C3C !important;
}
#preferences-prompt .preferences-cards .section-separator {
  border-top: 1px solid #DADADA;
  width: 350px;
  margin-bottom: 20px;
}
#preferences-prompt .preferences-cards .sf-link-account, #preferences-prompt .preferences-cards .sf-account {
  padding: 10px 0px 0px 10px;
  font-size: 14px;
  color: #D7DBDE;
  display: none;
}
#preferences-prompt .preferences-cards .sf-account {
  color: #333839;
}
#preferences-prompt .preferences-cards .linked-acct {
  float: left;
}
#preferences-prompt .preferences-cards .unlink-acct {
  float: right;
}
#preferences-prompt .preferences-cards .yw3-card {
  display: none;
  box-shadow: 0 1px 3px -1px #979797;
}
#preferences-prompt .preferences-cards .yw3-card .yw3-card-body {
  padding-bottom: 0px;
}
#preferences-prompt .preferences-cards input {
  font-family: "proxima-nova", arial, sans-serif;
  outline: none;
  padding-left: 5px;
}
#preferences-prompt .preferences-cards input:focus {
  border-bottom: 2px solid #29ABE2 !important;
}
#preferences-prompt .preferences-cards input[type=text]:disabled {
  color: #D7DBDE;
  border: 1px solid #F5F5F7;
  background-color: white;
}
#preferences-prompt .preferences-cards input[type=email]:enabled {
  color: #333839;
  border: 1px solid #D7DBDE;
}
#preferences-prompt .preferences-cards input[type=email].touched:invalid {
  box-shadow: none !important;
  border-bottom: 2px solid #E74C3C !important;
}
#preferences-prompt .preferences-cards .focused-style {
  color: #29ABE2;
}
#preferences-prompt .pref-card-short {
  height: 278px;
}
#preferences-prompt .preferences-cards::-webkit-scrollbar {
  -webkit-appearance: none;
  width: 11px;
}
#preferences-prompt .preferences-cards::-webkit-scrollbar-thumb {
  border-radius: 8px;
  border: 2px solid #F5F5F7;
  background-color: #7F7F7F;
}
#preferences-prompt preferences-cards::-webkit-scrollbar-track {
  border-radius: 8px;
}
#preferences-prompt .pref-screenshot {
  text-align: center;
}
#preferences-prompt .round-switch {
  position: relative;
  display: inline-block;
  width: 41px;
  height: 18px;
}
#preferences-prompt .round-switch input {
  display: none;
}
#preferences-prompt .round-slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #7F8A8C;
  -webkit-transition: 0.4s;
  transition: 0.4s;
  border-radius: 18px;
}
#preferences-prompt .round-slider:before {
  position: absolute;
  content: "";
  height: 16px;
  width: 16px;
  left: 1px;
  bottom: 1px;
  background-color: white;
  -webkit-transition: 0.4s;
  transition: 0.4s;
  border-radius: 50%;
}
#preferences-prompt input:checked + .round-slider {
  background-color: #29ABE2;
}
#preferences-prompt input:focus + .round-slider {
  box-shadow: 0 0 1px #29ABE2;
}
#preferences-prompt input:checked + .round-slider:before {
  -webkit-transform: translateX(23px);
  -ms-transform: translateX(23px);
  transform: translateX(23px);
}
#preferences-prompt .round-slider:after {
  content: "Off";
  color: white;
  display: block;
  position: absolute;
  transform: translate(-1px, -50%);
  top: 50%;
  left: 50%;
  font-size: 12px;
}
#preferences-prompt input:checked + .round-slider:after {
  content: "On";
  transform: translate(-100%, -50%);
}

