.yw-crmtour-main,
.yw-composertour-main,
.yw-send-tracked-email-tour-main,
.yw-composertour-composer-container {
  display: none;
  position: absolute;
  top: 60px;
  right: 60px;
  z-index: 10;
  width: 370px;
  background: #FFFFFF;
  border-top: 5px solid #8DC23C;
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.19), 0 6px 6px rgba(0, 0, 0, 0.23);
  padding: 20px;
  font-family: "proxima-nova", helvetica, arial, sans-serif;
  font-size: 14px;
  line-height: 21px;
  color: #576264;
}
.yw-crmtour-main h3,
.yw-composertour-main h3,
.yw-send-tracked-email-tour-main h3,
.yw-composertour-composer-container h3 {
  display: inline;
