.ibutton-container {
  position: relative;
  overflow: hidden;
  /* set max width to that of sprite */
  max-width: 400px;
  /* prevent text selection */
  -khtml-user-select: none;
  -o-user-select: none;
  -moz-user-select: none;
  -moz-user-focus: ignore;
  -moz-user-input: disabled;
  background: -webkit-gradient(linear, left top, left bottom, color-stop(0%, #3672dc), color-stop(100%, #76adfc));
  background: -moz-linear-gradient(top, #3672dc 0%, #76adfc 100%);
  box-shadow: inset 0 2px 2px #2a5bb3, inset -3px 0 3px #2a5bb3;
  border: 1px solid #999;
  border-radius: 3px;
  /* set default width based on ON/OFF labels */
  height: 18px;
  width: 68px;
  cursor: pointer;
}

.ibutton-container input {
  position: absolute;
  top: 0;
  left: 0;
  /* hide the element */
  filter: alpha(opacity=0);
  -moz-opacity: 0;
  opacity: 0;
  /* allow checking of input if visible */
  -moz-user-input: enabled !important;
}

.ibutton-handle {
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  padding-left: 4px;
  background: -webkit-gradient(linear, left top, left bottom, color-stop(0%, #cdcdcd), color-stop(100%, #fbfbfb));
  background: -moz-linear-gradient(top, #cdcdcd 0%, #fbfbfb 100%);
  border: 1px solid #919191;
  border-radius: 3px;
  box-shadow: inset 0 1px 0 #f0f0f0;
  height: 16px;
  width: 29px;
  cursor: inherit;
  z-index: 3;
}

.ibutton-handle-right {
  display: none;
}

.ibutton-handle-middle {
  display: none;
}

div.ibutton-label-on, div.ibutton-label-off {
  display: block;
  position: absolute;
  width: auto;
  top: 0;
  overflow: hidden;
  font-size: 12px;
  font-weight: bold;
  text-transform: uppercase;
  cursor: inherit;
  white-space: nowrap;
}
div.ibutton-label-on label, div.ibutton-label-off label {
  margin: 0 !important;
}

div.ibutton-label-on {
  color: #fff;
  text-shadow: 0 -1px 2px rgba(0, 0, 0, 0.4);
  left: 0;
  padding-top: 2px;
  padding-left: 4px;
  z-index: 1;
}

div.ibutton-label-on span {
  padding-left: 5px;
}

div.ibutton-label-off {
  color: #555;
  background: -webkit-linear-gradient(top, #cfcfcf, #efefef 50%, #f9f9f9 50%, #fefefe);
  background: -moz-linear-gradient(top, #cfcfcf, #efefef 50%, #f9f9f9 50%, #fefefe);
  box-shadow: inset 0 2px 2px #b6b6b6, inset 3px 0 3px #b6b6b6;
  text-shadow: 0 1px -2px rgba(255, 255, 255, 0.4);
  text-align: right;
  right: 0;
  /* the off label needs to near the left edge (ideally just 5px away)
     * it just needs to be close enough that it won't show under the handle if dragged to the left
     */
  width: 32px;
  padding-top: 2px;
  padding-right: 2px;
  border-top-right-radius: 3px;
  border-bottom-right-radius: 3px;
}
div.ibutton-label-off label {
  float: right !important;
  padding: 1px 2px;
}

/* make sure the "OFF" label appears even when zoomed in */
div.ibutton-label-off span {
  padding-right: 0px;
}

/* create an outline when button gets focus via keyboard */
.ibutton-container label {
  cursor: inherit;
  padding: 1px 3px;
  font-size: 1em !important;
}

.ibutton-focus label {
  /* we must use border, since outline doesn't work in IE */
  border: 1px dotted #666 !important;
  padding: 0 2px;
}

.ibutton-focus div.ibutton-label-on span label {
  /* use white for more contrast */
  border-color: #fff !important;
}

/* add padding to right/left so that text gets clipped before absolute edge */
.ibutton-padding-left, .ibutton-padding-right {
  display: none;
  /* Yesware override */
}

.ibutton-padding-left {
  left: 0;
}

.ibutton-padding-right {
  right: 0;
  background-position: 100% -4px;
}

/* change the styles of the handle when being dragged */
.ibutton-active-handle .ibutton-handle {
  background-position: 0 -108px;
}

.ibutton-active-handle .ibutton-handle-right {
  background-position: 100% -108px;
}

.ibutton-active-handle .ibutton-handle-middle {
  background-position: 50% -108px;
}

/* styles to use when the button is disabled */
.ibutton-disabled {
  cursor: not-allowed !important;
  /* cursor options: default or not-allowed */
  opacity: 0.7;
}

